/* Moleculox R137 · deferred expansion science bundle. Source payloads preserved in original order. */

/* ---- expansion-science-r92.js ---- */
/* Moleculox R92 · rich Moleculopedia science for Levels 316–325. */
Object.assign(MX_EXP_MOL_INFO,{"S2F2":{"about":{"tr":"Disülfür diflorür, iki kükürt ve iki flor atomundan oluşan S₂F₂ formüllü, reaktif bir kükürt–flor bileşiğidir.","en":"Disulfur difluoride, S₂F₂, is a reactive sulfur–fluorine compound containing two sulfur and two fluorine atoms.","de":"Dischwefeldifluorid, S₂F₂, ist eine reaktive Schwefel-Fluor-Verbindung aus zwei Schwefel- und zwei Fluoratomen.","es":"El difluoruro de disufre, S₂F₂, es un compuesto reactivo de azufre y flúor con dos átomos de cada elemento.","pt":"O difluoreto de dissulfureto, S₂F₂, é um composto reativo de enxofre e flúor com dois átomos de cada elemento.","ja":"二フッ化二硫黄S₂F₂は、硫黄2原子とフッ素2原子からなる反応性の高い硫黄–フッ素化合物です。","fr":"Le difluorure de disoufre, S₂F₂, est un composé réactif soufre–fluor contenant deux atomes de soufre et deux de fluor.","zh":"二氟化二硫S₂F₂是一种由两个硫原子和两个氟原子组成的活泼硫–氟化合物。","it":"Il difluoruro di dizolfo, S₂F₂, è un composto reattivo zolfo–fluoro formato da due atomi di zolfo e due di fluoro."},"use":{"tr":"Yaygın günlük kullanımı yoktur; kükürt–flor bağları ve reaktif florür türleri üzerine laboratuvar araştırmalarında incelenir.","en":"It has no common everyday use; it is studied in laboratory research on sulfur–fluorine bonding and reactive fluorine compounds.","de":"Es hat keine übliche Alltagsanwendung; es wird in Laborstudien zu Schwefel-Fluor-Bindungen und reaktiven Fluorverbindungen untersucht.","es":"No tiene un uso cotidiano común; se estudia en laboratorio para investigar enlaces azufre–flúor y compuestos fluorados reactivos.","pt":"Não tem uso cotidiano comum; é estudado em laboratório para investigar ligações enxofre–flúor e compostos fluorados reativos.","ja":"一般的な日常用途はなく、硫黄–フッ素結合や反応性フッ素化合物の研究で扱われます。","fr":"Il n’a pas d’usage quotidien courant ; il est étudié en laboratoire pour les liaisons soufre–fluor et les composés fluorés réactifs.","zh":"它没有常见日常用途，主要用于实验室研究硫–氟键以及活泼含氟物种。","it":"Non ha un uso quotidiano comune; viene studiato in laboratorio per i legami zolfo–fluoro e i composti fluorurati reattivi."},"fact":{"tr":"S₂F₂ için birden fazla yapısal düzen mümkündür; Moleculox hedefi F–S–S–F bağlantısını sadeleştirilmiş 2B biçimde gösterir.","en":"More than one structural arrangement is possible for S₂F₂; Moleculox shows a simplified 2D F–S–S–F connectivity.","de":"Für S₂F₂ sind mehrere Strukturformen möglich; Moleculox zeigt die F–S–S–F-Verknüpfung als vereinfachtes 2D-Modell.","es":"S₂F₂ puede presentar más de una disposición estructural; Moleculox muestra una conectividad F–S–S–F simplificada en 2D.","pt":"S₂F₂ pode apresentar mais de um arranjo estrutural; o Moleculox mostra uma conectividade F–S–S–F simplificada em 2D.","ja":"S₂F₂には複数の構造配置があり得ます。MoleculoxではF–S–S–Fのつながりを簡略化した2Dモデルで表します。","fr":"Plusieurs arrangements structuraux sont possibles pour S₂F₂ ; Moleculox montre une connectivité F–S–S–F simplifiée en 2D.","zh":"S₂F₂可以有不止一种结构排列；Moleculox以简化的2D形式表示F–S–S–F连接。","it":"Per S₂F₂ sono possibili più disposizioni strutturali; Moleculox mostra una connettività F–S–S–F semplificata in 2D."}},"H2CS":{"about":{"tr":"Tiyoformaldehit (CH₂S), formaldehitteki oksijenin kükürtle yer değiştirdiği, kısa ömürlü ve reaktif bir moleküldür.","en":"Thioformaldehyde, CH₂S, is a short-lived reactive molecule related to formaldehyde, with sulfur in place of oxygen.","de":"Thioformaldehyd, CH₂S, ist ein kurzlebiges reaktives Molekül, das dem Formaldehyd ähnelt, jedoch Schwefel statt Sauerstoff enthält.","es":"El tioformaldehído, CH₂S, es una molécula reactiva y de vida corta emparentada con el formaldehído, con azufre en lugar de oxígeno.","pt":"O tioformaldeído, CH₂S, é uma molécula reativa e de vida curta relacionada ao formaldeído, com enxofre no lugar do oxigênio.","ja":"チオホルムアルデヒドCH₂Sは、ホルムアルデヒドの酸素を硫黄に置き換えた、短寿命で反応性の高い分子です。","fr":"Le thioformaldéhyde, CH₂S, est une molécule réactive et de courte durée de vie apparentée au formaldéhyde, avec du soufre à la place de l’oxygène.","zh":"硫代甲醛CH₂S是一种寿命较短、反应性较高的分子，可看作把甲醛中的氧换成硫。","it":"La tioformaldeide, CH₂S, è una molecola reattiva e di breve durata simile alla formaldeide, con zolfo al posto dell’ossigeno."},"use":{"tr":"Kararlı bir ticari ürün olarak yaygın kullanılmaz; spektroskopi, reaksiyon mekanizmaları ve yıldızlararası kimya araştırmalarında incelenir.","en":"It is not widely used as a stable commercial product; it is studied in spectroscopy, reaction-mechanism research, and interstellar chemistry.","de":"Es wird nicht als stabiles Handelsprodukt genutzt; untersucht wird es in der Spektroskopie, bei Reaktionsmechanismen und in der interstellaren Chemie.","es":"No se usa de forma habitual como producto comercial estable; se estudia en espectroscopia, mecanismos de reacción y química interestelar.","pt":"Não é usado normalmente como produto comercial estável; é estudado em espectroscopia, mecanismos de reação e química interestelar.","ja":"安定した商業製品として一般利用されず、分光学、反応機構、星間化学の研究対象です。","fr":"Il n’est pas couramment utilisé comme produit commercial stable ; il est étudié en spectroscopie, en mécanismes réactionnels et en chimie interstellaire.","zh":"它并不是常见的稳定商业产品，主要用于光谱学、反应机理和星际化学研究。","it":"Non è comunemente usato come prodotto commerciale stabile; viene studiato in spettroscopia, nei meccanismi di reazione e nella chimica interstellare."},"fact":{"tr":"CH₂S yıldızlararası uzayda da tespit edilmiştir; bu, çok reaktif moleküllerin bile uzay kimyasında bulunabileceğini gösterir.","en":"CH₂S has also been detected in interstellar space, showing that highly reactive molecules can exist in space chemistry.","de":"CH₂S wurde auch im interstellaren Raum nachgewiesen – ein Beispiel dafür, dass selbst sehr reaktive Moleküle in der Weltraumchemie vorkommen.","es":"CH₂S también se ha detectado en el espacio interestelar, mostrando que moléculas muy reactivas pueden existir en la química espacial.","pt":"CH₂S também foi detectado no espaço interestelar, mostrando que moléculas muito reativas podem existir na química espacial.","ja":"CH₂Sは星間空間でも検出されており、高反応性分子も宇宙化学に存在できることを示しています。","fr":"CH₂S a aussi été détecté dans l’espace interstellaire, montrant que des molécules très réactives peuvent exister en chimie spatiale.","zh":"CH₂S也已在星际空间中被探测到，说明高度活泼的分子同样能够存在于宇宙化学环境中。","it":"CH₂S è stato rilevato anche nello spazio interstellare, mostrando che molecole molto reattive possono esistere nella chimica dello spazio."}},"NCl3":{"about":{"tr":"Azot triklorür (NCl₃), bir azot ve üç klor atomundan oluşan, çok hassas ve reaktif bir klor–azot bileşiğidir.","en":"Nitrogen trichloride, NCl₃, is a highly sensitive reactive chlorine–nitrogen compound containing one nitrogen and three chlorine atoms.","de":"Stickstofftrichlorid, NCl₃, ist eine sehr empfindliche, reaktive Chlor-Stickstoff-Verbindung aus einem Stickstoff- und drei Chloratomen.","es":"El tricloruro de nitrógeno, NCl₃, es un compuesto muy sensible y reactivo de cloro y nitrógeno con un átomo de nitrógeno y tres de cloro.","pt":"O tricloreto de nitrogênio, NCl₃, é um composto muito sensível e reativo de cloro e nitrogênio com um átomo de nitrogênio e três de cloro.","ja":"三塩化窒素NCl₃は、窒素1原子と塩素3原子からなる非常に敏感で反応性の高い化合物です。","fr":"Le trichlorure d’azote, NCl₃, est un composé chlore–azote très sensible et réactif contenant un atome d’azote et trois de chlore.","zh":"三氯化氮NCl₃由一个氮原子和三个氯原子组成，是一种非常敏感且活泼的氯–氮化合物。","it":"Il tricloruro di azoto, NCl₃, è un composto cloro–azoto molto sensibile e reattivo formato da un atomo di azoto e tre di cloro."},"use":{"tr":"Güvenli bir günlük kullanım maddesi değildir; istenmeyen bir yan ürün olarak oluşabileceği sistemlerde kontrol edilmesi ve önlenmesi önemlidir.","en":"It is not a material for routine practical use; when it can form as an unwanted by-product, controlling and preventing it is important.","de":"Es ist kein Stoff für die alltägliche Nutzung; wenn es als unerwünschtes Nebenprodukt entstehen kann, sind Kontrolle und Vermeidung wichtig.","es":"No es un material de uso práctico habitual; cuando puede formarse como subproducto no deseado, es importante controlarlo y evitarlo.","pt":"Não é um material de uso prático rotineiro; quando pode surgir como subproduto indesejado, é importante controlá-lo e evitá-lo.","ja":"日常的に利用する物質ではなく、望ましくない副生成物として生じ得る系では、その生成を抑えることが重要です。","fr":"Ce n’est pas une substance d’usage pratique courant ; lorsqu’elle peut se former comme sous-produit indésirable, il est important de la contrôler et de l’éviter.","zh":"它不是日常实用材料；在可能作为不希望副产物生成的系统中，控制并避免其形成十分重要。","it":"Non è una sostanza per l’uso pratico ordinario; quando può formarsi come sottoprodotto indesiderato è importante controllarne e prevenirne la formazione."},"fact":{"tr":"NCl₃ çok hassas olduğundan Moleculox’ta yalnızca güvenli bir dijital molekül modeli olarak gösterilir.","en":"Because NCl₃ is highly sensitive, Moleculox presents it only as a safe digital molecular model.","de":"Da NCl₃ sehr empfindlich ist, zeigt Moleculox es ausschließlich als sicheres digitales Molekülmodell.","es":"Como NCl₃ es muy sensible, Moleculox lo presenta únicamente como modelo molecular digital seguro.","pt":"Como NCl₃ é muito sensível, o Moleculox o apresenta apenas como um modelo molecular digital seguro.","ja":"NCl₃は非常に敏感なため、Moleculoxでは安全なデジタル分子モデルとしてのみ扱います。","fr":"NCl₃ étant très sensible, Moleculox le présente uniquement sous forme de modèle moléculaire numérique sûr.","zh":"由于NCl₃非常敏感，Moleculox只把它作为安全的数字分子模型呈现。","it":"Poiché NCl₃ è molto sensibile, Moleculox lo presenta esclusivamente come modello molecolare digitale sicuro."}},"SnF4":{"about":{"tr":"Kalay(IV) florür, SnF₄ formüllü, kalayın +4 yükseltgenme basamağında bulunduğu inorganik bir florür bileşiğidir.","en":"Tin(IV) fluoride, SnF₄, is an inorganic fluoride in which tin is in the +4 oxidation state.","de":"Zinn(IV)-fluorid, SnF₄, ist ein anorganisches Fluorid, in dem Zinn die Oxidationsstufe +4 besitzt.","es":"El fluoruro de estaño(IV), SnF₄, es un fluoruro inorgánico en el que el estaño está en estado de oxidación +4.","pt":"O fluoreto de estanho(IV), SnF₄, é um fluoreto inorgânico no qual o estanho está no estado de oxidação +4.","ja":"フッ化スズ(IV)SnF₄は、スズが+4の酸化状態をとる無機フッ化物です。","fr":"Le fluorure d’étain(IV), SnF₄, est un fluorure inorganique dans lequel l’étain est à l’état d’oxydation +4.","zh":"四氟化锡SnF₄是一种无机氟化物，其中锡处于+4氧化态。","it":"Il fluoruro di stagno(IV), SnF₄, è un fluoruro inorganico in cui lo stagno si trova nello stato di ossidazione +4."},"use":{"tr":"Özel flor kimyası ve kalay bileşikleri araştırmalarında reaktif veya başlangıç maddesi olarak kullanılabilir; yaygın bir tüketici ürünü değildir.","en":"It can serve as a reagent or starting material in specialized fluorine and tin chemistry; it is not a common consumer product.","de":"Es kann als Reagenz oder Ausgangsstoff in spezieller Fluor- und Zinnchemie dienen und ist kein gewöhnliches Verbraucherprodukt.","es":"Puede servir como reactivo o material de partida en química especializada del flúor y del estaño; no es un producto de consumo común.","pt":"Pode servir como reagente ou material de partida em química especializada de flúor e estanho; não é um produto de consumo comum.","ja":"特殊なフッ素化学やスズ化学で試薬・出発物質として使われることがありますが、一般消費財ではありません。","fr":"Il peut servir de réactif ou de matériau de départ en chimie spécialisée du fluor et de l’étain ; ce n’est pas un produit de consommation courant.","zh":"它可在专门的氟化学和锡化学中作为试剂或起始材料，并非常见消费品。","it":"Può essere usato come reagente o materiale di partenza nella chimica specializzata del fluoro e dello stagno; non è un comune prodotto di consumo."},"fact":{"tr":"SnF₄ katı halde iyonik/polimerik etkileşimler gösterebilir; oyundaki artı biçimi gerçek 3B yapının sadeleştirilmiş hedefidir.","en":"Solid SnF₄ can show extended bonding interactions; the cross in Moleculox is a simplified 2D target rather than its full 3D solid structure.","de":"Festes SnF₄ kann ausgedehnte Bindungswechselwirkungen zeigen; das Kreuz in Moleculox ist nur ein vereinfachtes 2D-Ziel, nicht die vollständige 3D-Festkörperstruktur.","es":"El SnF₄ sólido puede mostrar interacciones de enlace extendidas; la cruz de Moleculox es un objetivo 2D simplificado y no su estructura sólida 3D completa.","pt":"O SnF₄ sólido pode apresentar interações de ligação estendidas; a cruz no Moleculox é um alvo 2D simplificado, não a estrutura sólida 3D completa.","ja":"固体SnF₄では広がった結合相互作用が見られます。Moleculoxの十字形は実際の3D固体構造ではなく、簡略化した2D目標です。","fr":"Le SnF₄ solide peut présenter des interactions de liaison étendues ; la croix de Moleculox est une cible 2D simplifiée et non sa structure solide 3D complète.","zh":"固态SnF₄可表现出延伸的成键相互作用；Moleculox中的十字形只是简化的2D目标，并非完整3D固体结构。","it":"Lo SnF₄ solido può mostrare interazioni di legame estese; la croce di Moleculox è un bersaglio 2D semplificato, non la sua struttura solida 3D completa."}},"COS":{"about":{"tr":"Karbonil sülfür (COS), doğrusal O=C=S bağlantısına sahip, atmosferde doğal olarak bulunan küçük bir kükürt bileşiğidir.","en":"Carbonyl sulfide, COS, is a small naturally occurring sulfur compound with a roughly linear O=C=S molecular framework.","de":"Carbonylsulfid, COS, ist eine kleine natürlich vorkommende Schwefelverbindung mit annähernd linearer O=C=S-Struktur.","es":"El sulfuro de carbonilo, COS, es un pequeño compuesto natural de azufre con una estructura molecular aproximadamente lineal O=C=S.","pt":"O sulfeto de carbonila, COS, é um pequeno composto natural de enxofre com estrutura molecular aproximadamente linear O=C=S.","ja":"硫化カルボニルCOSは、ほぼ直線状のO=C=S骨格をもつ、自然界にも存在する小さな硫黄化合物です。","fr":"Le sulfure de carbonyle, COS, est un petit composé soufré naturel à squelette moléculaire approximativement linéaire O=C=S.","zh":"羰基硫COS是一种自然存在的小型含硫化合物，分子骨架近似直线形O=C=S。","it":"Il solfuro di carbonile, COS, è un piccolo composto naturale dello zolfo con una struttura molecolare approssimativamente lineare O=C=S."},"use":{"tr":"Kimyasal sentez ve kükürt kimyasında bir ara madde olarak kullanılabilir; ayrıca atmosfer ve iklim araştırmalarında önemli bir iz gazıdır.","en":"It can be used as an intermediate in chemical synthesis and sulfur chemistry, and it is also an important trace gas in atmospheric research.","de":"Es kann als Zwischenprodukt in Synthese und Schwefelchemie dienen und ist außerdem ein wichtiges Spurengas in der Atmosphärenforschung.","es":"Puede utilizarse como intermedio en síntesis y química del azufre, y también es un gas traza importante en investigación atmosférica.","pt":"Pode ser usado como intermediário em síntese e química do enxofre, além de ser um gás-traço importante em pesquisas atmosféricas.","ja":"化学合成や硫黄化学の中間体として利用されることがあり、大気研究でも重要な微量気体です。","fr":"Il peut servir d’intermédiaire en synthèse et en chimie du soufre ; c’est aussi un gaz trace important en recherche atmosphérique.","zh":"它可作为化学合成和硫化学中的中间体，也是大气研究中的重要痕量气体。","it":"Può essere usato come intermedio nella sintesi e nella chimica dello zolfo ed è anche un importante gas in tracce nella ricerca atmosferica."},"fact":{"tr":"COS, Dünya atmosferindeki en bol kükürt içeren gazlardan biridir ve stratosferik kükürt döngüsüne katkı sağlayabilir.","en":"COS is one of the most abundant sulfur-containing gases in Earth’s atmosphere and can contribute to the stratospheric sulfur cycle.","de":"COS gehört zu den häufigsten schwefelhaltigen Gasen der Erdatmosphäre und kann zum Schwefelkreislauf der Stratosphäre beitragen.","es":"COS es uno de los gases con azufre más abundantes de la atmósfera terrestre y puede contribuir al ciclo de azufre estratosférico.","pt":"COS é um dos gases contendo enxofre mais abundantes da atmosfera terrestre e pode contribuir para o ciclo de enxofre na estratosfera.","ja":"COSは地球大気中で比較的多い含硫黄気体の一つで、成層圏の硫黄循環にも関与します。","fr":"COS est l’un des gaz soufrés les plus abondants de l’atmosphère terrestre et peut contribuer au cycle stratosphérique du soufre.","zh":"COS是地球大气中较丰富的含硫气体之一，并可参与平流层硫循环。","it":"COS è uno dei gas contenenti zolfo più abbondanti nell’atmosfera terrestre e può contribuire al ciclo dello zolfo stratosferico."}},"HOF":{"about":{"tr":"Hipofloröz asit (HOF), hidrojen, oksijen ve flordan oluşan, çok reaktif ve kararsız bir oksijen–flor bileşiğidir.","en":"Hypofluorous acid, HOF, is a highly reactive and unstable oxygen–fluorine compound containing hydrogen, oxygen, and fluorine.","de":"Hypofluorige Säure, HOF, ist eine sehr reaktive und instabile Sauerstoff-Fluor-Verbindung aus Wasserstoff, Sauerstoff und Fluor.","es":"El ácido hipofluoroso, HOF, es un compuesto de oxígeno y flúor muy reactivo e inestable que contiene hidrógeno, oxígeno y flúor.","pt":"O ácido hipofluoroso, HOF, é um composto de oxigênio e flúor muito reativo e instável que contém hidrogênio, oxigênio e flúor.","ja":"次亜フッ素酸HOFは、水素・酸素・フッ素からなる非常に反応性が高く不安定な酸素–フッ素化合物です。","fr":"L’acide hypofluoreux, HOF, est un composé oxygène–fluor très réactif et instable contenant hydrogène, oxygène et fluor.","zh":"次氟酸HOF由氢、氧、氟组成，是一种反应性很高且不稳定的氧–氟化合物。","it":"L’acido ipofluoroso, HOF, è un composto ossigeno–fluoro molto reattivo e instabile formato da idrogeno, ossigeno e fluoro."},"use":{"tr":"Rutin günlük kullanımı yoktur; güçlü oksitleyici özellikleri nedeniyle kontrollü laboratuvar kimyası ve temel araştırmalarda incelenir.","en":"It has no routine everyday use; its strong oxidizing chemistry is studied in carefully controlled laboratory and fundamental research.","de":"Es hat keine alltägliche Routineanwendung; seine stark oxidierende Chemie wird unter sorgfältig kontrollierten Laborbedingungen erforscht.","es":"No tiene un uso cotidiano habitual; su fuerte química oxidante se estudia en investigación básica y de laboratorio cuidadosamente controlada.","pt":"Não tem uso cotidiano rotineiro; sua forte química oxidante é estudada em pesquisas fundamentais e de laboratório cuidadosamente controladas.","ja":"日常的な用途はなく、強い酸化性をもつ化学種として厳密に管理された基礎・実験研究で扱われます。","fr":"Il n’a pas d’usage quotidien courant ; sa forte chimie oxydante est étudiée dans des recherches fondamentales et de laboratoire soigneusement contrôlées.","zh":"它没有常规日常用途，其强氧化性主要在严格受控的实验室和基础研究中研究。","it":"Non ha un uso quotidiano ordinario; la sua forte chimica ossidante viene studiata in ricerche fondamentali e di laboratorio attentamente controllate."},"fact":{"tr":"HOF sıradışı bir moleküldür çünkü oksijen ile flor arasında doğrudan bir O–F bağı içerir.","en":"HOF is unusual because it contains a direct oxygen–fluorine O–F bond.","de":"HOF ist ungewöhnlich, weil es eine direkte Sauerstoff-Fluor-Bindung O–F enthält.","es":"HOF es inusual porque contiene un enlace directo oxígeno–flúor O–F.","pt":"HOF é incomum porque contém uma ligação direta oxigênio–flúor O–F.","ja":"HOFは酸素とフッ素が直接つながるO–F結合を含む点で珍しい分子です。","fr":"HOF est inhabituel car il contient une liaison directe oxygène–fluor O–F.","zh":"HOF的特别之处在于它含有直接的氧–氟O–F键。","it":"HOF è insolito perché contiene un legame diretto ossigeno–fluoro O–F."}},"COCl2":{"about":{"tr":"Karbonil klorür (COCl₂), fosgen olarak da bilinen, bir karbonil merkezi ve iki klor içeren son derece toksik bir moleküldür.","en":"Carbonyl chloride, COCl₂, also called phosgene, is an extremely toxic molecule with a carbonyl center and two chlorine atoms.","de":"Carbonylchlorid, COCl₂, auch Phosgen genannt, ist ein äußerst giftiges Molekül mit einem Carbonylzentrum und zwei Chloratomen.","es":"El cloruro de carbonilo, COCl₂, también llamado fosgeno, es una molécula extremadamente tóxica con un centro carbonilo y dos átomos de cloro.","pt":"O cloreto de carbonila, COCl₂, também chamado fosgênio, é uma molécula extremamente tóxica com um centro carbonila e dois átomos de cloro.","ja":"塩化カルボニルCOCl₂（ホスゲン）は、カルボニル中心と2個の塩素をもつ非常に有毒な分子です。","fr":"Le chlorure de carbonyle, COCl₂, aussi appelé phosgène, est une molécule extrêmement toxique avec un centre carbonyle et deux atomes de chlore.","zh":"碳酰氯COCl₂又称光气，是一种毒性极强的分子，含有一个羰基中心和两个氯原子。","it":"Il cloruro di carbonile, COCl₂, noto anche come fosgene, è una molecola estremamente tossica con un centro carbonilico e due atomi di cloro."},"use":{"tr":"Kapalı endüstriyel sistemlerde bazı polimer ve kimyasal ara maddelerin üretiminde kullanılır; yüksek toksisitesi nedeniyle sıkı mühendislik kontrolleri gerektirir.","en":"It is used in closed industrial systems to make some polymer and chemical intermediates; its high toxicity requires strict engineering controls.","de":"Es wird in geschlossenen Industrieanlagen zur Herstellung mancher Polymer- und Chemiezwischenprodukte eingesetzt; wegen seiner hohen Giftigkeit sind strenge technische Kontrollen nötig.","es":"Se utiliza en sistemas industriales cerrados para fabricar algunos polímeros e intermedios químicos; su alta toxicidad exige controles de ingeniería estrictos.","pt":"É usado em sistemas industriais fechados para produzir alguns polímeros e intermediários químicos; sua alta toxicidade exige controles de engenharia rigorosos.","ja":"一部のポリマーや化学中間体の製造で閉鎖型工業設備内に使用されますが、高い毒性のため厳格な工学的管理が必要です。","fr":"Il est utilisé dans des systèmes industriels fermés pour fabriquer certains polymères et intermédiaires chimiques ; sa forte toxicité exige des contrôles techniques stricts.","zh":"它在封闭工业系统中用于制造部分聚合物和化学中间体；由于毒性极高，需要严格的工程控制。","it":"Viene usato in sistemi industriali chiusi per produrre alcuni polimeri e intermedi chimici; la sua elevata tossicità richiede rigorosi controlli ingegneristici."},"fact":{"tr":"COCl₂ tarihsel olarak kimyasal silah olarak da kullanılmıştır; Moleculox yalnızca güvenli moleküler model ve bilimsel bağlam sunar.","en":"COCl₂ was also used historically as a chemical weapon; Moleculox presents it only as a safe molecular model with scientific context.","de":"COCl₂ wurde historisch auch als chemische Waffe eingesetzt; Moleculox zeigt es ausschließlich als sicheres Molekülmodell im wissenschaftlichen Kontext.","es":"COCl₂ también se utilizó históricamente como arma química; Moleculox lo presenta únicamente como modelo molecular seguro con contexto científico.","pt":"COCl₂ também foi usado historicamente como arma química; o Moleculox o apresenta apenas como modelo molecular seguro com contexto científico.","ja":"COCl₂は歴史的に化学兵器としても使用されました。Moleculoxでは安全な分子モデルとして科学的文脈のみを扱います。","fr":"COCl₂ a aussi été utilisé historiquement comme arme chimique ; Moleculox le présente uniquement comme modèle moléculaire sûr dans un contexte scientifique.","zh":"COCl₂历史上也曾被用作化学武器；Moleculox只以安全的分子模型和科学背景来呈现它。","it":"COCl₂ è stato usato storicamente anche come arma chimica; Moleculox lo presenta solo come modello molecolare sicuro in un contesto scientifico."}},"XeO4":{"about":{"tr":"Ksenon tetroksit (XeO₄), ksenonun çok yüksek yükseltgenme basamağında bulunduğu, dört oksijenli son derece kararsız bir soy gaz oksididir.","en":"Xenon tetroxide, XeO₄, is an extremely unstable noble-gas oxide containing xenon in a very high oxidation state and four oxygen atoms.","de":"Xenontetroxid, XeO₄, ist ein äußerst instabiles Edelgasoxid mit Xenon in sehr hoher Oxidationsstufe und vier Sauerstoffatomen.","es":"El tetróxido de xenón, XeO₄, es un óxido de gas noble extremadamente inestable con xenón en un estado de oxidación muy alto y cuatro oxígenos.","pt":"O tetróxido de xenônio, XeO₄, é um óxido de gás nobre extremamente instável, com xenônio em estado de oxidação muito alto e quatro oxigênios.","ja":"四酸化キセノンXeO₄は、非常に高い酸化状態のキセノンと4個の酸素からなる極めて不安定な希ガス酸化物です。","fr":"Le tétroxyde de xénon, XeO₄, est un oxyde de gaz noble extrêmement instable contenant du xénon à un état d’oxydation très élevé et quatre oxygènes.","zh":"四氧化氙XeO₄是一种极不稳定的稀有气体氧化物，氙处于很高的氧化态并与四个氧原子相连。","it":"Il tetrossido di xeno, XeO₄, è un ossido di gas nobile estremamente instabile con xeno in uno stato di ossidazione molto elevato e quattro atomi di ossigeno."},"use":{"tr":"Pratik veya ticari kullanımı yoktur; soy gazların bağ yapısı ve yüksek yükseltgenme basamaklarını anlamaya yönelik temel araştırmalarda önemlidir.","en":"It has no practical or commercial use; it is important mainly for fundamental research on noble-gas bonding and high oxidation states.","de":"Es hat keine praktische oder kommerzielle Anwendung; wichtig ist es vor allem für Grundlagenforschung zu Edelgasbindungen und hohen Oxidationsstufen.","es":"No tiene uso práctico o comercial; su importancia está principalmente en la investigación básica sobre enlaces de gases nobles y altos estados de oxidación.","pt":"Não tem uso prático ou comercial; sua importância é principalmente na pesquisa fundamental sobre ligações de gases nobres e altos estados de oxidação.","ja":"実用・商業用途はなく、希ガスの結合や高酸化状態を理解する基礎研究で重要です。","fr":"Il n’a pas d’usage pratique ou commercial ; son intérêt est surtout fondamental pour l’étude des liaisons des gaz nobles et des états d’oxydation élevés.","zh":"它没有实际或商业用途，主要价值在于研究稀有气体成键和高氧化态的基础化学。","it":"Non ha un uso pratico o commerciale; è importante soprattutto nella ricerca fondamentale sui legami dei gas nobili e sugli alti stati di ossidazione."},"fact":{"tr":"XeO₄, soy gazların tamamen tepkisiz olduğu düşüncesine meydan okuyan en uç ksenon–oksijen örneklerinden biridir.","en":"XeO₄ is one of the most extreme xenon–oxygen examples showing that noble gases are not completely chemically inert.","de":"XeO₄ ist eines der extremsten Xenon-Sauerstoff-Beispiele dafür, dass Edelgase chemisch nicht völlig inert sind.","es":"XeO₄ es uno de los ejemplos xenón–oxígeno más extremos que muestran que los gases nobles no son completamente inertes.","pt":"XeO₄ é um dos exemplos mais extremos de xenônio–oxigênio que mostram que gases nobres não são totalmente inertes.","ja":"XeO₄は、希ガスが完全に化学的不活性ではないことを示す、最も極端なキセノン–酸素化合物の一例です。","fr":"XeO₄ est l’un des exemples xénon–oxygène les plus extrêmes montrant que les gaz nobles ne sont pas totalement inertes chimiquement.","zh":"XeO₄是最极端的氙–氧化合物例子之一，说明稀有气体并非在化学上完全惰性。","it":"XeO₄ è uno degli esempi xeno–ossigeno più estremi che mostrano come i gas nobili non siano completamente inerti chimicamente."}},"CH2O":{"about":{"tr":"Formaldehit (CH₂O), en basit aldehittir; bir karbon, bir oksijen ve iki hidrojen içerir ve oda koşullarında gazdır.","en":"Formaldehyde, CH₂O, is the simplest aldehyde; it contains one carbon, one oxygen, and two hydrogens and is a gas at ordinary conditions.","de":"Formaldehyd, CH₂O, ist der einfachste Aldehyd; es enthält ein Kohlenstoff-, ein Sauerstoff- und zwei Wasserstoffatome und ist unter Normalbedingungen gasförmig.","es":"El formaldehído, CH₂O, es el aldehído más simple; contiene un carbono, un oxígeno y dos hidrógenos y es gaseoso en condiciones normales.","pt":"O formaldeído, CH₂O, é o aldeído mais simples; contém um carbono, um oxigênio e dois hidrogênios e é gasoso em condições comuns.","ja":"ホルムアルデヒドCH₂Oは最も単純なアルデヒドで、炭素1・酸素1・水素2からなり、通常条件では気体です。","fr":"Le formaldéhyde, CH₂O, est l’aldéhyde le plus simple ; il contient un carbone, un oxygène et deux hydrogènes et est gazeux dans les conditions ordinaires.","zh":"甲醛CH₂O是最简单的醛，含一个碳、一个氧和两个氢，在通常条件下为气体。","it":"La formaldeide, CH₂O, è l’aldeide più semplice; contiene un carbonio, un ossigeno e due idrogeni ed è un gas in condizioni ordinarie."},"use":{"tr":"Reçine, yapıştırıcı ve çeşitli malzemelerin üretiminde önemli bir endüstriyel hammaddedir; sulu çözeltileri kontrollü koşullarda koruyucu olarak da kullanılır.","en":"It is an important industrial feedstock for resins, adhesives, and other materials; aqueous solutions are also used as preservatives under controlled conditions.","de":"Es ist ein wichtiger industrieller Rohstoff für Harze, Klebstoffe und andere Materialien; wässrige Lösungen werden unter kontrollierten Bedingungen auch zur Konservierung genutzt.","es":"Es una materia prima industrial importante para resinas, adhesivos y otros materiales; sus soluciones acuosas también se usan como conservantes bajo condiciones controladas.","pt":"É uma matéria-prima industrial importante para resinas, adesivos e outros materiais; soluções aquosas também são usadas como conservantes em condições controladas.","ja":"樹脂・接着剤などの材料製造で重要な工業原料で、水溶液は管理された条件で保存用途にも使われます。","fr":"C’est une matière première industrielle importante pour les résines, adhésifs et autres matériaux ; ses solutions aqueuses servent aussi de conservateurs dans des conditions contrôlées.","zh":"它是树脂、胶黏剂等材料的重要工业原料，其水溶液在受控条件下也用于保存。","it":"È un’importante materia prima industriale per resine, adesivi e altri materiali; le soluzioni acquose sono usate anche come conservanti in condizioni controllate."},"fact":{"tr":"Formaldehit insan metabolizmasında da çok küçük miktarlarda doğal olarak oluşur; ancak yüksek maruziyet sağlığa zararlıdır.","en":"Very small amounts of formaldehyde also occur naturally in human metabolism, but significant exposure is hazardous to health.","de":"Sehr kleine Mengen Formaldehyd entstehen auch natürlich im menschlichen Stoffwechsel, doch eine stärkere Exposition ist gesundheitsschädlich.","es":"Pequeñas cantidades de formaldehído también se producen de forma natural en el metabolismo humano, pero una exposición importante es peligrosa para la salud.","pt":"Pequenas quantidades de formaldeído também surgem naturalmente no metabolismo humano, mas uma exposição significativa é prejudicial à saúde.","ja":"ホルムアルデヒドは人体の代謝でもごく少量自然に生じますが、高い曝露は健康に有害です。","fr":"De très petites quantités de formaldéhyde apparaissent naturellement dans le métabolisme humain, mais une exposition importante est dangereuse pour la santé.","zh":"人体代谢中也会自然产生极少量甲醛，但较高水平的暴露会危害健康。","it":"Piccolissime quantità di formaldeide si formano naturalmente anche nel metabolismo umano, ma un’esposizione significativa è dannosa per la salute."}},"SO3":{"about":{"tr":"Kükürt trioksit (SO₃), bir kükürt ve üç oksijen atomundan oluşan, suyla çok güçlü şekilde tepkimeye giren bir kükürt oksididir.","en":"Sulfur trioxide, SO₃, is a sulfur oxide containing one sulfur and three oxygen atoms that reacts very strongly with water.","de":"Schwefeltrioxid, SO₃, ist ein Schwefeloxid aus einem Schwefel- und drei Sauerstoffatomen, das sehr stark mit Wasser reagiert.","es":"El trióxido de azufre, SO₃, es un óxido de azufre con un átomo de azufre y tres de oxígeno que reacciona muy intensamente con el agua.","pt":"O trióxido de enxofre, SO₃, é um óxido de enxofre com um átomo de enxofre e três de oxigênio que reage muito intensamente com a água.","ja":"三酸化硫黄SO₃は硫黄1原子と酸素3原子からなる硫黄酸化物で、水と非常に激しく反応します。","fr":"Le trioxyde de soufre, SO₃, est un oxyde de soufre contenant un atome de soufre et trois d’oxygène qui réagit très fortement avec l’eau.","zh":"三氧化硫SO₃由一个硫原子和三个氧原子组成，与水反应非常强烈。","it":"Il triossido di zolfo, SO₃, è un ossido di zolfo formato da un atomo di zolfo e tre di ossigeno che reagisce molto intensamente con l’acqua."},"use":{"tr":"Başlıca sülfürik asit üretiminde ve endüstriyel sülfonasyon işlemlerinde kullanılır; yüksek reaktivitesi nedeniyle kapalı ve kontrollü sistemlerde işlenir.","en":"It is used mainly in sulfuric-acid production and industrial sulfonation processes and is handled in closed, controlled systems because of its high reactivity.","de":"Es wird vor allem zur Schwefelsäureherstellung und bei industriellen Sulfonierungen verwendet und wegen seiner hohen Reaktivität in geschlossenen, kontrollierten Systemen gehandhabt.","es":"Se utiliza sobre todo en la producción de ácido sulfúrico y en procesos industriales de sulfonación, y se maneja en sistemas cerrados y controlados por su alta reactividad.","pt":"É usado principalmente na produção de ácido sulfúrico e em processos industriais de sulfonação, sendo manipulado em sistemas fechados e controlados devido à alta reatividade.","ja":"主に硫酸製造や工業的スルホン化に使われ、反応性が高いため閉鎖・管理された設備で扱われます。","fr":"Il est surtout utilisé pour produire l’acide sulfurique et dans les procédés industriels de sulfonation ; sa forte réactivité impose des systèmes fermés et contrôlés.","zh":"它主要用于硫酸生产和工业磺化过程；由于反应性很高，需要在封闭且受控的系统中处理。","it":"È usato soprattutto nella produzione di acido solforico e nei processi industriali di solfonazione; per l’elevata reattività viene gestito in sistemi chiusi e controllati."},"fact":{"tr":"SO₃ suyla birleştiğinde sülfürik asit oluşumuna gider; atmosferdeki sülfat aerosollerinin kimyasında da önemli bir ara basamaktır.","en":"When SO₃ combines with water it leads to sulfuric acid, and it is also an important intermediate in atmospheric sulfate-aerosol chemistry.","de":"Wenn SO₃ mit Wasser reagiert, entsteht Schwefelsäure; außerdem ist es ein wichtiges Zwischenprodukt der atmosphärischen Sulfat-Aerosol-Chemie.","es":"Cuando SO₃ se combina con agua conduce a ácido sulfúrico y también es un intermedio importante en la química atmosférica de aerosoles de sulfato.","pt":"Quando SO₃ se combina com água, leva à formação de ácido sulfúrico e também é um intermediário importante na química atmosférica de aerossóis de sulfato.","ja":"SO₃が水と反応すると硫酸の生成につながり、大気中の硫酸塩エアロゾル化学でも重要な中間体です。","fr":"Lorsque SO₃ se combine à l’eau, il conduit à l’acide sulfurique ; c’est aussi un intermédiaire important de la chimie atmosphérique des aérosols sulfatés.","zh":"SO₃与水结合会形成硫酸，同时也是大气硫酸盐气溶胶化学中的重要中间体。","it":"Quando SO₃ si combina con l’acqua porta alla formazione di acido solforico ed è anche un importante intermedio nella chimica atmosferica degli aerosol di solfato."}}});

